import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Element-wise addition (reused from the example) ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b)"
)
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Depthwise 2D convolution (square kernel) ----------
conv2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Output size for a square input of height H_in, width W_in with padding p, stride s and kernel k.
int out_h = (H + 2*p - k) / s + 1;
int out_w = (W + 2*p - k) / s + 1;

__global__ void conv2d_depthwise_kernel(const float* __restrict__ input,
                                        const float* __restrict__ kernel,
                                        float* __restrict__ output,
                                        int batch_size, int in_channels,
                                        int H_in, int W_in,
                                        int k, int s, int p) {
    // Each thread processes one element of the output tensor.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * in_channels * out_h * out_w) {
        int b = idx / (in_channels * out_h * out_w);
        int rem = idx % (in_channels * out_h * out_w);
        int ch = rem / (out_h * out_w);
        rem = rem % (out_h * out_w);
        int oh = rem / in_channels;
        int ow = rem % in_channels;

        float sum = 0.0f;
        for (int iy = -p; iy < p; ++iy) {
            for (int ix = -p; ix < p; ++ix) {
                int in_h = oh + iy;
                int in_w = ow + ix;
                if (in_h >= 0 && in_h < H_in && in_w >= 0 && in_w < W_in) {
                    // Input index
                    int idx_in = b * in_channels * H_in * W_in + ch * H_in * W_in + in_h * W_in + in_w;
                    sum += input[idx_in] * kernel[b * k * k + ch * k * k + in_h * k + in_w];
                }
            }
        }
        output[idx] = sum;
    }
}

torch::Tensor depthwise_conv2d_cuda(torch::Tensor x) {
    // For stride=1, padding=0 we can compute output size as H_in - k + 1.
    int out_h = (x.size(2) - k + 1);
    int out_w = (x.size(3) - k + 1);

    auto batch_size = x.size(0);
    int in_channels = x.size(1);
    int H_in = x.size(2);
    int W_in = x.size(3);

    torch::Tensor out = torch::zeros(batch_size, in_channels, out_h, out_w);

    const int block_size = 256;
    const int num_blocks = ((out.size(0) * in_channels * out_h * out_w + block_size - 1) / block_size);

    conv2d_depthwise_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), x.nelement()? # type: ignore : None, out.data_ptr<float>(), batch_size, in_channels, H_in, W_in, k, 1, 0);  # type: ignore

    return out;
}
"""

# ---------- Load the custom conv2d function ----------
conv2d_custom = load_inline(
    name="depthwise_conv2d",
    cpp_sources=conv2d_source,
    cuda_sources=conv2d_source,  # placeholder; we need separate source for function definition.
    functions=["depthwise_conv2d_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- ModelNew class (optimized with custom CUDA operators) ----------
class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.elementwise_add = elementwise_add
        # Store the custom conv2d function as an attribute (not a nn.Conv2d)
        self.depthwise_conv_cuda = conv2d_custom

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs depthwise 2D convolution with square kernel.
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width).
        Returns:
            Output tensor after depthwise conv.
        """
        return self.depthwise_conv_cuda(x)
